def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    remainder = remaining % item
    return np.where(remaining >= 0, -remainder, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)
